import { Step } from './types';

export function runLoop(steps: Step[]): void {
  const maxRetries = 5;
  let retryCount = 0;

  for (const step of steps) {
    while (retryCount < maxRetries) {
      try {
        step.execute();
        retryCount = 0; // Reset retry count on success
        break;
      } catch (error) {
        retryCount++;
        console.error(`Step ${step.name} failed. Retrying...`);
      }
    }
    if (retryCount >= maxRetries) {
      console.error(`Step ${step.name} failed after ${maxRetries} retries. Aborting.`);
      break;
    }
  }
}

