export class StateManager {
  private state: AgentState;
  private persistenceInterval: number = 5000; // 5 seconds
  private saveInterval: NodeJS.Timeout;

  constructor(state: AgentState) {
    this.state = state;
    this.startSaveInterval();
  }

  private startSaveInterval() {
    this.saveInterval = setInterval(() => this.saveState(), this.persistenceInterval);
  }

  private saveState() {
    try {
      const serializedState = JSON.stringify(this.state);
      const fs = require('fs');
      fs.writeFileSync('agent_state.json', serializedState);
      console.log('Agent state saved to disk.');
    } catch (error) {
      console.error('Failed to save agent state:', error);
    }
  }

  public setState(newState: AgentState) {
    this.state = newState;
    this.saveState();
  }

  public stopSaveInterval() {
    clearInterval(this.saveInterval);
  }
}

